                raise ValueError("invalid stored session identity")
            context = validate_context(raw)
            attempt_id = session.last_attempt_id
            if attempt_id is not None and not OBJECT_ID.fullmatch(attempt_id):
                raise ValueError("invalid stored attempt identity")
        except (ValueError, TypeError, KeyError) as exc:
            excluded += 1
            logger.warning("Selection session metadata unavailable: %s", type(exc).__name__)
            continue
        selected = []
        for attempt in attempts_by_session.get(session.session_id, []):
            try:
                if not isinstance(attempt.attempt_id, str) or not OBJECT_ID.fullmatch(attempt.attempt_id):
                    raise ValueError("invalid stored attempt identity")
                if attempt.attempt_id != session.last_attempt_id and not _has_candidates(session.session_id, attempt.attempt_id):
                    continue
            except (OSError, ValueError, TypeError, KeyError) as exc:
                excluded += 1
                logger.warning("Selection attempt metadata unavailable: %s", type(exc).__name__)
                continue
            selected.append(attempt)
        for attempt in selected or [None]:
            attempt_id = attempt.attempt_id if attempt else None
            identity = "opportunity:" + session.session_id + (":" + attempt_id if attempt_id else "")
            item = {"id": hashlib.sha256(identity.encode()).hexdigest()[:32],
                "title": session.title or _title(context), "kind": "research", "input": context,
                "createdAt": attempt.created_at if attempt else session.created_at,
                "updatedAt": (attempt.completed_at or attempt.created_at) if attempt else session.updated_at,
                "status": getattr(attempt.status, "value", attempt.status) if attempt else "not_started",
                "sessionId": session.session_id}
            if attempt is not None:
                item["attemptId"] = attempt_id
            items.append(item)
    items.sort(key=lambda item: (item["createdAt"], item["id"]), reverse=True)
    return {"items": items[offset:offset + limit], "total": len(items), "limit": limit,
            "offset": offset, "excluded": excluded}
